Clase Punto
  Definir x Como Entero;
  Definir yy Como Entero;
FinClase

Algoritmo Puntos
  Definir p Como Punto <- Nuevo Punto();
  p.x <- 3;
  p.yy <- 4;
  Escribir p.x, ",", p.yy;
FinAlgoritmo

Clase Caja
  Privado Definir secreto Como Entero;
FinClase

Algoritmo Espiar
  Definir c Como Caja <- Nuevo Caja();
  c.secreto <- 1;
FinAlgoritmo
